2	/**
3	 * Tenky obal nad PDO.
4	 *
5	 * Puvodne obal nad mysql_* funkcemi (2014), v roce 2016 prepsano na PDO,
6	 * protoze hosting prestal podporovat ext/mysql. Rozhrani zustalo stejne,
7	 * aby se nemusely prepisovat vsechny stranky v administraci.
8	 *
9	 * @author petr
10	 * @author jana.k (PDO prepis)
11	 */
12	
13	namespace App\Legacy\lib;
14	
15	class LegacyDb
16	{
17	    /** @var \PDO */
18	    private $pdo;
19	
20	    private $dsn;
21	
22	    // pocitadlo dotazu pro debug lištu (viz templates/partials/footer.php)
23	    public $queryCount = 0;
24	
25	    public $lastSql = '';
26	
27	    // TODO: logovani pomalych dotazu, nekdy...
28	    public $log = array();
29	
30	    public function __construct($dsn, $user = null, $pass = null)
31	    {
32	        $this->dsn = $dsn;
33	        $this->pdo = new \PDO($dsn, $user, $pass);
34	        // jana.k 2016: zapnuto, at to nepada potichu jako driv
35	        $this->pdo->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
36	        $this->pdo->setAttribute(\PDO::ATTR_DEFAULT_FETCH_MODE, \PDO::FETCH_ASSOC);
37	
38	        if (strpos($dsn, 'mysql:') === 0) {
39	            // puvodne bezelo na MySQL 5.5, kodovani se nastavovalo rucne
40	            $this->pdo->exec("SET NAMES utf8");
41	        }
42	    }
43	
44	    /**
45	     * Vrati vsechny radky jako pole asociativnich poli.
46	     */
47	    public function query($sql)
48	    {
49	        $this->queryCount++;
50	        $this->lastSql = $sql;
51	        $stmt = $this->pdo->query($sql);
52	        if ($stmt === false) {
53	            return array();
54	        }
55	        $rows = $stmt->fetchAll(\PDO::FETCH_ASSOC);
56	        $stmt->closeCursor();
57	
58	        return $rows;
59	    }
60	
61	    /**
62	     * Prvni radek nebo null.
63	     */
64	    public function one($sql)
65	    {
66	        $rows = $this->query($sql);
67	        if (count($rows) == 0) {
68	            return null;
69	        }
70	
71	        return $rows[0];
72	    }
73	
74	    /**
75	     * Prvni sloupec prvniho radku (napr. COUNT(*)).
76	     */
77	    public function value($sql)
78	    {
79	        $row = $this->one($sql);
80	        if ($row === null) {
81	            return null;
82	        }
83	        $vals = array_values($row);
84	
85	        return $vals[0];
86	    }
87	
88	    /**
89	     * INSERT/UPDATE/DELETE, vraci pocet ovlivnenych radku.
90	     */
91	    public function exec($sql)
92	    {
93	        $this->queryCount++;
94	        $this->lastSql = $sql;
95	        $res = $this->pdo->exec($sql);
96	
97	        return $res === false ? 0 : $res;
98	    }
99	
100	    public function quote($value)
101	    {
102	        if ($value === null) {
103	            return 'NULL';
104	        }
105	        if (is_bool($value)) {
106	            return $value ? '1' : '0';
107	        }
108	
109	        return $this->pdo->quote((string) $value);
110	    }
111	
112	    public function lastId()
113	    {
114	        return $this->pdo->lastInsertId();
115	    }
116	
117	    public function begin()
118	    {
119	        return $this->pdo->beginTransaction();
120	    }
121	
122	    public function commit()
123	    {
124	        return $this->pdo->commit();
125	    }
126	
127	    public function rollback()
128	    {
129	        if ($this->pdo->inTransaction()) {
130	            return $this->pdo->rollBack();
131	        }
132	
133	        return false;
134	    }
135	
136	    public function isSqlite()
137	    {
138	        return strpos($this->dsn, 'sqlite:') === 0;
139	    }
140	
141	    /**
142	     * Pro pripad nouze. Nepouzivat v novem kodu!
143	     */
144	    public function getPdo()
145	    {
146	        return $this->pdo;
147	    }
148	
149	    // stara metoda z mysql doby, uz se nevola (snad)
150	    public function escape($value)
151	    {
152	        return substr($this->quote($value), 1, -1);
153	    }
154	}
